    public static function job($key,$lock=false){global $wpdb;if(!is_string($key)||!preg_match('/^[a-f0-9-]{36}$/D',$key))return CAFCC_Repository::error('Invalid action key.');$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('jobs').' WHERE job_key=%s AND owner_id=%d'.($lock?' FOR UPDATE':''),$key,get_current_user_id()),ARRAY_A);if(!$r)return CAFCC_Repository::error('Private action not found.',404);$r['records']=json_decode($r['payload'],true)['records'];$r['selection']=json_decode($r['payload'],true)['selection'];$r['canonical']=json_decode($r['payload'],true)['canonical']??array();$r['canonical_cursor']=(int)(json_decode($r['payload'],true)['canonical_cursor']??0);$r['report']=json_decode($r['report'],true);unset($r['payload']);return $r;}
