        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;return CAFCC_Academic::transaction(function()use($key,$input){global $wpdb;$job=self::job($key,true);if(is_wp_error($job))return $job;$cursor=(int)$job['cursor_position'];if(!isset($input['cursor'])||!is_int($input['cursor']))return CAFCC_Repository::error('Supply the current integer cursor.');if($input['cursor']<$cursor||$job['phase']==='completed')return $job;if($input['cursor']!==$cursor)return CAFCC_Repository::error('Action cursor changed. Resume it.',409);$planning=$job['phase']==='planning';
