                if($error){$job['report']['blocked'][(string)$row['id']]=array('id'=>(int)$row['id'],'stable_id'=>$r['stable_id']??'','message'=>$error->get_error_message());$job['records'][$cursor]['blocked']=true;}elseif(!$planning&&($row['blocked']??false)){} }
            if($planning&&$cursor===count($job['records'])){$job['phase']='ready';$cursor=0;}elseif(!$planning&&$cursor===count($job['records']))$job['phase']='completed';$job['cursor_position']=$cursor;
            if(false===$wpdb->update(self::table('jobs'),array('cursor_position'=>$cursor,'phase'=>$job['phase'],'confirmed_at'=>$job['confirmed_at'],'payload'=>wp_json_encode(array('selection'=>$job['selection'],'records'=>$job['records'],'canonical'=>$job['canonical'],'canonical_cursor'=>$job['canonical_cursor'])),'report'=>wp_json_encode($job['report'])),array('id'=>$job['id']))||!CAFCC_Bank_DB::audit_master('owner_batch_step',$job['id'],null,array('phase'=>$job['phase'],'cursor'=>$cursor,'administrator'=>get_current_user_id(),'independent_verification'=>false)))return CAFCC_Repository::error('Batch checkpoint could not be retained.',500);return self::job($key);
        });
    }
    public static function preview_quality($r){return self::quality($r);}
    public static function attempt_matches($ed,$attempt){$normalise=function($v){return strtolower(preg_replace('/[^a-z0-9]+/i','',$v));};$bundle=json_decode(file_get_contents(dirname(__DIR__).'/data/taxonomy-v04-proposals.json'),true);$rule=$bundle['attempt_rules'][$ed['edition_key']]??null;if($rule&&isset($rule['attempts']))return in_array($normalise($attempt),array_map($normalise,$rule['attempts']),true);if($rule&&isset($rule['from'])){$time=strtotime('1 '.$attempt.' UTC');if(!$time)return false;$date=gmdate('Y-m',$time);return $date>=$rule['from']&&(!isset($rule['until'])||$date<=$rule['until']);}return $normalise($attempt)!==''&&str_contains($normalise($ed['applicability']),$normalise($attempt));}
    public static function apply_record($r,$action){
        if($action==='publish')return self::publish($r['id'],$r['revision']);if($action==='drafts')return array('id'=>$r['id'],'status'=>'retained');return CAFCC_Academic::transaction(function()use($r,$action){global $wpdb;$values=array('revision'=>(int)$r['revision']+1,'modified_at'=>current_time('mysql',true));if($action==='archive'){if($r['publication_status']==='published')return CAFCC_Repository::error('Unpublish this record before archiving. Student history is retained.');$values['archived']=1;}elseif($action==='restore')$values['archived']=0;else{$values['publication_status']='draft';$values['status']='needs_review';}if(false===$wpdb->update(CAFCC_Studio::table(),$values,array('id'=>$r['id']))||!CAFCC_Studio::audit(CAFCC_Studio::get($r['id']),'owner_'.$action))return CAFCC_Repository::error('Action audit failed.',500);return array('id'=>$r['id'],'action'=>$action);});
    }
    public static function correct($id,$input){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_array($input)||array_diff(array_keys($input),array('expected_revision','question','answer','tags','notes','classification','action','accept_provisional','restore_id','resolved_warnings')))return CAFCC_Repository::error('Unexpected correction fields.');return CAFCC_Academic::transaction(function()use($id,$input){$r=CAFCC_Studio::get($id,true);if(!$r||(string)($input['expected_revision']??'')!==(string)$r['revision'])return CAFCC_Repository::error('Stale correction. Reload this question.',409);$d=$r['data'];if(isset($input['restore_id'])){global $wpdb;$snapshot=$wpdb->get_var($wpdb->prepare('SELECT snapshot FROM '.CAFCC_Bank_DB::table('audit').' WHERE id=%d AND review_id=%d',(int)$input['restore_id'],$id));$prior=json_decode($snapshot?:'null',true);if(!$prior||empty($prior['data']['rich_content']))return CAFCC_Repository::error('Historical revision not found for this question.');$d['rich_content']=$prior['data']['rich_content'];$d['answer']=$prior['data']['answer'];$d['classification']=$prior['data']['classification'];$input['tags']=array_column($prior['search_tags']??array(),'label');$d['review_notes'].="\nRestored historical content as a new draft revision.";}foreach(array('question','answer') as $kind)if(isset($input[$kind])){if(!is_string($input[$kind])||strlen($input[$kind])>500000)return CAFCC_Repository::error('Content exceeds its safe limit.');if($input[$kind]!==($d['rich_content'][$kind]['body_html']??'')){$d['rich_content'][$kind]['checks']=array('owner_edit_not_source_reverified'=>true);$d['rich_content'][$kind]['structure']=array('owner_edited'=>true);}$d['rich_content'][$kind]['body_html']=$input[$kind];}if(isset($input['classification']))$d['classification']=$input['classification'];if(isset($input['notes']))$d['review_notes']=$input['notes'];if(($input['action']??'')==='withdraw_answer'){$d['answer']=array();$d['review_notes'].="\nAnswer withdrawn by owner; prior revisions retained.";}$re