    }
    public static function init(){add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r,true);};register_rest_route('cafcc/v8','/admin/package-preview/(?P<id>[1-9][0-9]*)',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){global $wpdb;$id=(int)$r['id'];$items=$wpdb->get_results($wpdb->prepare('SELECT kind,payload FROM '.CAFCC_Package::items_table().' WHERE package_id=%d ORDER BY ordinal',$id),ARRAY_A);$out=array('count'=>0,'question_bodies'=>0,'answer_candidates'=>0,'sources'=>0,'samples'=>array(),'existing_rights_active'=>false);foreach($items as $i){$v=json_decode($i['payload'],true);if($i['kind']==='rights')$out['existing_rights_active']=(bool)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.CAFCC_Rights::table()." WHERE state='active' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.declaration_key'))=%s",$v['declaration_key']));if($i['kind']!=='questions')continue;foreach($v['records'] as $d){$out['count']++;$out['question_bodies']+=!empty($d['rich_content']['question']['body_html']);$out['answer_candidates']+=!empty($d['answer']);$out['sources']+=!empty($d['official_url']);if(count($out['samples'])<3)$out['samples'][]=array('label'=>$d['source_key'].' Q'.$d['reference'].($d['subreference']?'('.$d['subreference'].')':''),'question'=>CAFCC_Practice::html($d['rich_content']['question']['body_html']??''),'answer'=>CAFCC_Practice::html($d['rich_content']['answer']['body_html']??''));}}return $out;}));register_rest_route('cafcc/v8','/admin/library',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){return self::library($r->get_params());}));register_rest_route('cafcc/v8','/admin/packages',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function(){return array('items'=>self::packages(),'current'=>(int)get_option('cafcc_current_package',0));}));register_rest_route('cafcc/v8','/admin/package-sync/(?P<id>[1-9][0-9]*)',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function